class Solution:
    def aggregateTimeSeries(self, series1: list[list[int]], series2: list[list[int]]) -> list[list[int]]:
        n1, n2 = len(series1), len(series2)
        next1 = [0] * n1
        next2 = [0] * n2

        for i in range(n1 - 2, -1, -1):
            next1[i] = series1[i + 1][1]
        for i in range(n2 - 2, -1, -1):
            next2[i] = series2[i + 1][1]

        i = j = 0
        res = []

        while i < n1 and j < n2:
            t1, t2 = series1[i][0], series2[j][0]
            if t1 == t2:
                res.append([t1, series1[i][1] + series2[j][1]])
                i += 1
                j += 1
            elif t1 < t2:
                res.append([t1, series1[i][1] + series2[j][1]])
                i += 1
            else:
                res.append([t2, next1[i] + series2[j][1]])
                j += 1

        while i < n1:
            res.append([series1[i][0], series1[i][1]])
            i += 1

        while j < n2:
            res.append([series2[j][0], series2[j][1]])
            j += 1

        return res

